// 入力例 1 のとき:
//   input[0] は "(()())"

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const s = readFileSync(0, "utf8").trim();

// depth は「まだ閉じていない ( の数」
let depth = 0;
let ok = true;
for (const c of s) {
  depth += c === "(" ? 1 : -1;
  if (depth < 0) {
    ok = false; // 対応する ( がない ) が現れた
    break;
  }
}
console.log(ok && depth === 0 ? "Yes" : "No");
